drop function public.training_seed_into(text, jsonb);

do $$
begin
  if exists (select 1 from pg_trigger where tgname = 'log_tree_changes') then
    alter table public.trees enable trigger log_tree_changes;
  end if;
end $$;

-- ===========================================================================
-- Did it take? Self-contained: it reads only the tables themselves.
-- ===========================================================================
select 'training trees' as check,
       (select count(*) from public.trees where is_training) = 150 as ok,
       (select count(*) from public.trees where is_training)::text as detail
union all
select 'training permits', (select count(*) from public.permits where is_training) = 11,
       (select count(*) from public.permits where is_training)::text
union all
select 'training tags', (select count(*) from public.pending_trees where is_training) = 12,
       (select count(*) from public.pending_trees where is_training)::text
union all
select 'training arborists', (select count(*) from public.arborists where is_training) = 3,
       (select count(*) from public.arborists where is_training)::text
union all
select 'the activity log is paused no longer',
       not exists (select 1 from pg_trigger where tgname = 'log_tree_changes' and tgenabled = 'D'), ''
union all
select 'READ: left out of ' || seeded.tbl || ' (no such column)', null, string_agg(seeded.k, ', ' order by seeded.k)
from (values
  ('arborists', 'name'),
  ('arborists', 'email'),
  ('arborists', 'status'),
  ('arborists', 'is_training'),
  ('trees', 'id'),
  ('trees', 'tree_id'),
  ('trees', 'latitude'),
  ('trees', 'longitude'),
  ('trees', 'barangay'),
  ('trees', 'barangay_psgc'),
  ('trees', 'municipality'),
  ('trees', 'species'),
  ('trees', 'scientific_name'),
  ('trees', 'species_type'),
  ('trees', 'biodiversity_status'),
  ('trees', 'tree_category'),
  ('trees', 'dbh'),
  ('trees', 'merchantable_height'),
  ('trees', 'total_height'),
  ('trees', 'heightClass'),
  ('trees', 'height_class'),
  ('trees', 'stem_quality'),
  ('trees', 'isLeaning'),
  ('trees', 'hasPowerlineConflict'),
  ('trees', 'isRootProblem'),
  ('trees', 'isDecayed'),
  ('trees', 'assigned_to'),
  ('trees', 'has_cutting_permit'),
  ('trees', 'task_status'),
  ('trees', 'source'),
  ('trees', 'is_tagged'),
  ('trees', 'dateCaptured'),
  ('trees', 'is_training'),
  ('permits', 'tree_id'),
  ('permits', 'client_name'),
  ('permits', 'contact_info'),
  ('permits', 'reason'),
  ('permits', 'requirements_urls'),
  ('permits', 'species'),
  ('permits', 'number_of_trees'),
  ('permits', 'address'),
  ('permits', 'latitude'),
  ('permits', 'longitude'),
  ('permits', 'created_at'),
  ('permits', 'is_training'),
  ('pending_trees', 'species'),
  ('pending_trees', 'barangay'),
  ('pending_trees', 'municipality'),
  ('pending_trees', 'lgu_psgc'),
  ('pending_trees', 'latitude'),
  ('pending_trees', 'longitude'),
  ('pending_trees', 'status'),
  ('pending_trees', 'assigned_to'),
  ('pending_trees', 'submitted_at'),
  ('pending_trees', 'is_training')
) seeded(tbl, k)
where not exists (select 1 from information_schema.columns c
                  where c.table_schema = 'public' and c.table_name = seeded.tbl and c.column_name = seeded.k)
group by seeded.tbl;
